const takeGroupInvite = `-- name: TakeGroupInvite :one
DELETE FROM group_invites WHERE id = $1 AND invitee_id = $2 RETURNING group_id
`

type TakeGroupInviteParams struct {
	ID        uuid.UUID
	InviteeID uuid.UUID
}

func (q *Queries) TakeGroupInvite(ctx context.Context, arg TakeGroupInviteParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, takeGroupInvite, arg.ID, arg.InviteeID)
	var group_id uuid.UUID
	err := row.Scan(&group_id)
	return group_id, err
}

const unsetWatchReady = `-- name: UnsetWatchReady :exec
DELETE FROM watch_ready WHERE session_id = $1 AND user_id = $2
`

type UnsetWatchReadyParams struct {
	SessionID uuid.UUID
	UserID    uuid.UUID
}

func (q *Queries) UnsetWatchReady(ctx context.Context, arg UnsetWatchReadyParams) error {
	_, err := q.db.Exec(ctx, unsetWatchReady, arg.SessionID, arg.UserID)
	return err
}

const updateGroupChannel = `-- name: UpdateGroupChannel :exec
UPDATE group_channels SET name = coalesce($1, name),
    topic = CASE WHEN $2::bool THEN $3 ELSE topic END
WHERE id = $4
`

type UpdateGroupChannelParams struct {
	Name     *string
	SetTopic bool
	Topic    *string
	ID       uuid.UUID
}

// A null name leaves it; set_topic replaces the topic with sqlc.narg(topic) (null clears it).
func (q *Queries) UpdateGroupChannel(ctx context.Context, arg UpdateGroupChannelParams) error {
	_, err := q.db.Exec(ctx, updateGroupChannel,
		arg.Name,
		arg.SetTopic,
		arg.Topic,
		arg.ID,
	)
	return err
}

const watchPartyReady = `-- name: WatchPartyReady :many
SELECT r.user_id, p.handle, u.display_name, u.avatar_version
FROM watch_ready r JOIN profiles p ON p.user_id = r.user_id JOIN users u ON u.id = r.user_id
WHERE r.session_id = $1
ORDER BY p.handle
`

type WatchPartyReadyRow struct {
	UserID        uuid.UUID
	Handle        string
	DisplayName   *string
	AvatarVersion *int64
}

func (q *Queries) WatchPartyReady(ctx context.Context, sessionID uuid.UUID) ([]WatchPartyReadyRow, error) {
	rows, err := q.db.Query(ctx, watchPartyReady, sessionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WatchPartyReadyRow{}
	for rows.Next() {
		var i WatchPartyReadyRow
		if err := rows.Scan(
			&i.UserID,
			&i.Handle,
			&i.DisplayName,
			&i.AvatarVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
